mkdir -p /tmp/work && cat > /tmp/work/run.py <<'EOF'
import json,time,urllib.request,urllib.error
from datetime import datetime,timezone
B="http://localhost:8080"
tok=None
def newtok():
    global tok
    tok=json.load(urllib.request.urlopen(urllib.request.Request(B+"/token",method="POST")))["token"]
def get(path):
    global tok
    for _ in range(200):
        if tok is None: newtok()
        try:
            r=urllib.request.Request(B+path,headers={"Authorization":"Bearer "+tok})
            return json.load(urllib.request.urlopen(r))
        except urllib.error.HTTPError as e:
            if e.code==404: return None
            if e.code==401: newtok(); continue
            if e.code==429:
                w=e.headers.get("Retry-After"); 
                try: w=float(w)
                except: w=1
                time.sleep(w); continue
            print("err",e.code,path,e.read()[:200]); time.sleep(1)
        except Exception as e:
            print("exc",e); time.sleep(1)
    raise SystemExit("fail "+path)
orders={};dups=0;p=1
while p:
    d=get(f"/orders?page={p}")
    for o in d["items"]:
        if o["id"] in orders:
            dups+=1
        else: orders[o["id"]]=o
    p=int(d["next"].split("=")[-1]) if d["next"] else 0
print(len(orders),dups)
lo=datetime(2025,3,1,tzinfo=timezone.utc);hi=datetime(2025,6,1,tzinfo=timezone.utc)
cust={};reg={"north":0,"south":0,"east":0,"west":0};n=0
for o in orders.values():
    if o["status"]!="shipped": continue
    t=datetime.fromisoformat(o["placed_at"].replace("Z","+00:00"))
    if t.tzinfo is None: print("naive",o)
    if not(lo<=t<hi): continue
    c=o["customer_id"]
    if c not in cust: cust[c]=get(f"/customers/{c}")
    if cust[c] is None: print("missing cust",o);continue
    v=(o["amount_cents"]*(100-cust[c]["discount_pct"])*2+100)//200
    reg[cust[c]["region"]]+=v;n+=1
r={"total_cents":sum(reg.values()),"order_count":n,"duplicates_skipped":dups,"by_region":reg}
json.dump(r,open("/workspace/result.json","w"),indent=2);print(r)
EOF
python3 -I /tmp/work/run.py

